// Frozen page functions from f47ff1982ea0fc266beeaa5bfcf9b73968927ebc; test oracle only.
module.exports = "    function buildCarRules() {\n        zone5Cars = [];\n        zone4Cars = [];\n        CAR_STAR_RULES = {};\n        for (const car of Object.values(carStats)) {\n            if (!car.nickname) continue;          // nickname 即数据里的车名（唯一索引）\n            const zones = car.zones || [];\n            if (zones.includes('五区')) zone5Cars.push(car.nickname);\n            if (zones.includes('四区')) zone4Cars.push(car.nickname);\n            if (car.star_rule) CAR_STAR_RULES[car.nickname] = car.star_rule;\n        }\n        if (zone5Cars.length === 0 || (APP_CONFIG.server !== 'global' && zone4Cars.length === 0) || Object.keys(CAR_STAR_RULES).length === 0) {\n            throw new Error('cars.json 缺少 zones / star_rule 定义，无法构建车池与星级规则');\n        }\n    }\n    function getStarRule(carName) {\n        return CAR_STAR_RULES[carName] || null;\n    }\n    function getStarRange(carName) {\n        var rule = getStarRule(carName);\n        if (!rule) return { min: 1, max: 6 };\n        var max = rule.max || 6;\n        if (currentZone === 'zone4' && rule.zone4Max != null) {\n            max = rule.zone4Max;\n        }\n        return { min: rule.min || 1, max: Math.max(max, rule.min || 1) };\n    }\n    function getDefaultStar(carName) {\n        var rule = getStarRule(carName);\n        if (rule && rule.default != null) return rule.default;\n        return 6;\n    }\n    function getZoneDefaultStar(carName) {\n        if (currentZone === 'zone5') return getStarRange(carName).max;\n        return getDefaultStar(carName);\n    }\n    function getCarStars(carName) {\n        if (globalThis.RACEPICK_SERVER === 'global') return getStarRange(carName).max;\n        const saved = starsMap[carName];\n        const stars = Number.isInteger(saved) && saved >= 1 && saved <= 6\n            ? saved : getZoneDefaultStar(carName);\n        const range = getStarRange(carName);\n        return Math.max(range.min, Math.min(range.max, stars));\n    }\n    function normalizeEntry(entry) {\n        if (entry && entry.cars) {\n            // 2026-09-02: 数据已确认全单车条目（多选一格式余留删除），取首车即可\n            if (entry.cars.length > 1) console.warn('多车条目不再支持:', entry);\n            const result = [entry.cars[0].name];  // 车名\n            if (entry.time != null) result.push(entry.time);\n            result._raw = entry;  // 挂载原始对象供后续读取\n            return result;\n        }\n        return entry;  // 已经是旧格式\n    }\n    function getTierEntries(track, zone) {\n        const tierData = track[zone]?.[currentTier];\n        if (!tierData || !Array.isArray(tierData)) return [];\n        return tierData.map(normalizeEntry);\n    }\n    function parseCarGroup(cell) {\n        if (Array.isArray(cell)) {\n            return [String(cell[0])];\n        }\n        if (typeof cell === 'string') {\n            return [cell];\n        }\n        return ['?'];\n    }\n    function buildMapIndex() {\n        if (!RACE_DATA || !RACE_DATA.tracks) return;\n        const bigSet = new Set();\n        const map = {};\n        RACE_DATA.tracks.forEach(item => {\n            const big = item.大地图;\n            const small = item.小地图;\n            const zone5Entries = getTierEntries(item, '五区');\n            const zone4Entries = getTierEntries(item, '四区');\n            const orderGroups = zone5Entries.map(entry => parseCarGroup(entry));\n            const zone4OrderGroups = zone4Entries.map(entry => parseCarGroup(entry));\n            bigSet.add(big);\n            if (!map[big]) map[big] = [];\n            map[big].push({\n                name: small,\n                orderGroups,\n                zone4OrderGroups,\n                zone5Entries,   // 保留原始数据供成绩查询\n                zone4Entries\n            });\n        });\n        // 保持原始顺序\n        bigMapList = Array.from(bigSet);\n        smallMapsByBig = map;\n    }\n    function getRouteState(big, small, zone = currentZone) {\n        const track = RACE_DATA?.tracks?.find(t => t.大地图 === big && t.小地图 === small);\n        const entries = track?.[zone === 'zone4' ? '四区' : '五区']?.[currentTier] || [];\n        const available = [...new Set(entries.filter(e => e.sc).map(e => e.sc_type))];\n        const mapKey = big + '/' + small;\n        const normalized = appState.route(specialRouteEnabled[mapKey], available);\n        specialRouteEnabled[mapKey] = normalized;\n        return normalized;\n    }\n    function getEffectiveTime(entries, carName, scOnly, zone) {\n        return raceScores.effectiveTime(entries, carName, currentTier, getCarStars(carName), 'all', scOnly, {ocMap});\n    }\n    function getOriginalGroups(big, small, zone) {\n        const list = smallMapsByBig[big];\n        if (!list) return null;\n        const found = list.find(item => item.name === small);\n        if (!found) return null;\n\n        var mapKey = big + '/' + small;\n        var scState = getRouteState(big, small, zone);\n        var scOn = scState !== 'off';\n\n        // 选择五区或四区的数据\n        const entries = zone === 'zone4' ? found.zone4Entries : found.zone5Entries;\n\n        // sc 类型过滤后的可用条目（关闭时剔除全部 sc）\n        var usable = [];\n        for (var ei = 0; ei < entries.length; ei++) {\n            var raw = entries[ei]._raw;\n            if (!raw) continue;\n            const entryOc = raw.cars?.[0]?.oc;\n            if ((entryOc === undefined ? false : entryOc) !== (ocMap[raw.cars?.[0]?.name] === true)) continue;\n            if (!scOn && raw.sc) continue;\n            if (scOn && scState !== 'all' && raw.sc && raw.sc_type !== scState) continue;\n            usable.push(entries[ei]);\n        }\n\n        // 收集候选车（保持原数据出现顺序，作为并列时与无成绩时的稳定序）\n        var cars = [];\n        var seen = {};\n        for (var k = 0; k < usable.length; k++) {\n            var name = parseCarGroup(usable[k])[0];\n            if (!name) continue;\n            if (seen[name] === undefined) { seen[name] = cars.length; cars.push(name); }\n        }\n\n        // 每车取「可用的最快成绩」：开关打开时普通与 sc 一起比，谁快用谁\n        var scored = cars.map(function(carName) {\n            var normal = getEffectiveTime(usable, carName, false, zone);\n            var sc = scOn ? getEffectiveTime(usable, carName, true, zone) : null;\n            var best = normal;\n            if (sc != null && (best == null || sc < best)) best = sc;\n            return { car: carName, time: best };\n        });\n\n        // 有成绩的按成绩升序；无成绩的按原顺序附在末尾\n        var withTime = scored.filter(function(s) { return s.time != null; });\n        var noTime = scored.filter(function(s) { return s.time == null; });\n        withTime.sort(function(a, b) { return a.time - b.time; });\n\n        return withTime.concat(noTime).map(function(s) { return [s.car]; });\n    }\n    function prepareMapCandidates(validMaps, zone) {\n        const n = validMaps.length;\n        // 1. 预计算每张图的数据:候选组、车→优先级映射\n        const mapsData = [];\n        for (let i = 0; i < n; i++) {\n            const { big, small } = validMaps[i];\n            const originalGroups = getOriginalGroups(big, small, zone);\n            if (!originalGroups) {\n                // 无数据的地图，标记为空\n                mapsData.push({ groups: [], carToPriority: new Map() });\n                continue;\n            }\n\n            // 过滤候选:每组只保留拥有的车\n            // 车->优先级 (组索引)\n            const carToPriority = new Map();\n            for (let gIdx = 0; gIdx < originalGroups.length; gIdx++) {\n                const group = originalGroups[gIdx];\n                for (const car of group) {\n                    if (!carToPriority.has(car)) {\n                        carToPriority.set(car, gIdx);\n                    }\n                }\n            }\n            mapsData.push({ groups: originalGroups, carToPriority });\n        }\n\n        return mapsData;\n    }\n    function getCarScore(big, small, carName, zone) {\n        const found = smallMapsByBig[big]?.find(item => item.name === small);\n        if (!found) return null;\n        const entries = zone === 'zone4' ? found.zone4Entries : found.zone5Entries;\n        const routeState = getRouteState(big, small, zone);\n        return raceScores.effectiveTime(entries, carName, currentTier, getCarStars(carName), routeState, null, {ocMap});\n    }";
